        let cache_path = fetcher.cache_path(url);

        // Create a cached file
        std::fs::create_dir_all(cache_path.parent().unwrap()).unwrap();
        std::fs::write(&cache_path, "test content").unwrap();
        assert!(cache_path.exists());

